// Fixed-volume optimisation slider: square-based box, V = 64 cm^3.
const OPT_V = 64;
function optSA(x) { return 2 * x * x + 4 * OPT_V / x; }
function optFmt(n) { return Math.round(n * 100) / 100; }
const OPT_G = { x0: 44, y0: 160, xs: 260 / 7, ys: 146 / 280 };
function optGx(x) { return OPT_G.x0 + (x - 1) * OPT_G.xs; }
function optGy(s) { return OPT_G.y0 - s * OPT_G.ys; }
(function optBuildGraph() {
  let d = '';
  for (let x = 1; x <= 8.0001; x += 0.05) d += (d ? ' L' : 'M') + optGx(x).toFixed(1) + ' ' + optGy(optSA(x)).toFixed(1);
  document.getElementById('optCurve').setAttribute('d', d);
  let t = '';
  for (let x = 1; x <= 8; x++) t += '<text x="' + optGx(x) + '" y="173" text-anchor="middle">' + x + '</text>';
  [0, 100, 200].forEach(function (s) { t += '<text x="39" y="' + (optGy(s) + 3) + '" text-anchor="end">' + s + '</text>'; });
  document.getElementById('optTicks').innerHTML = t;
})();
function optUpdate() {
  const x = parseFloat(document.getElementById('optX').value);
  const h = OPT_V / (x * x);
  const sa = optSA(x);
  // oblique drawing scaled to fit 320 x 200
  const s = Math.min(150 / (x * 1.55), 150 / (h + 0.55 * x));
  const L = Math.max(x * s, 8), H = Math.max(h * s, 6), D = Math.max(x * s * 0.55, 6);
  const x0 = 60, y0 = 180, fx1 = x0 + L, fy0 = y0 - H;
  document.getElementById('optFront').setAttribute('points', x0 + ',' + y0 + ' ' + fx1 + ',' + y0 + ' ' + fx1 + ',' + fy0 + ' ' + x0 + ',' + fy0);
  document.getElementById('optTop').setAttribute('points', x0 + ',' + fy0 + ' ' + fx1 + ',' + fy0 + ' ' + (fx1 + D) + ',' + (fy0 - D) + ' ' + (x0 + D) + ',' + (fy0 - D));
  document.getElementById('optSide').setAttribute('points', fx1 + ',' + y0 + ' ' + (fx1 + D) + ',' + (y0 - D) + ' ' + (fx1 + D) + ',' + (fy0 - D) + ' ' + fx1 + ',' + fy0);
  const lx = document.getElementById('optLblX');
  lx.setAttribute('x', x0 + L / 2); lx.setAttribute('y', Math.min(y0 + 15, 197)); lx.textContent = optFmt(x) + ' cm';
  const lh = document.getElementById('optLblH');
  lh.setAttribute('x', x0 - 6); lh.setAttribute('y', y0 - H / 2 + 4); lh.textContent = optFmt(h) + ' cm';
  const dot = document.getElementById('optDot');
  dot.setAttribute('cx', optGx(x)); dot.setAttribute('cy', optGy(sa));
  document.getElementById('optXVal').textContent = optFmt(x);
  document.getElementById('optBase').textContent = optFmt(x) + ' × ' + optFmt(x);
  document.getElementById('optH').textContent = optFmt(h);
  document.getElementById('optV').textContent = optFmt(x * x * h);
  document.getElementById('optSA').textContent = optFmt(sa);
  const st = document.getElementById('optStatus');
  st.textContent = ''; st.classList.remove('win');
}
function optCheck() {
  const x = parseFloat(document.getElementById('optX').value);
  const st = document.getElementById('optStatus');
  st.classList.remove('win');
  if (x === 4) {
    st.classList.add('win');
    st.textContent = '✓ Yes! x = 4 cm, h = 4 cm: a cube, with SA = 96 cm², the lowest point on the graph.';
  } else {
    st.textContent = 'Not yet: SA here is ' + optFmt(optSA(x)) + ' cm². Look for the lowest point on the graph.';
  }
}
optUpdate();
function pickHingeOption(btn) {
  if (btn.classList.contains('dimmed')) return;
  const isCorrect = btn.dataset.correct === 'true';
  btn.classList.add('selected', isCorrect ? 'correct' : 'incorrect');
  document.querySelectorAll('.hinge-opt').forEach(o => { if (o !== btn) o.classList.add('dimmed'); });
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
  const fbId = btn.dataset.feedbackId;
  if (fbId) document.getElementById(fbId).classList.add('visible');
}
function resetHinge() {
  document.querySelectorAll('.hinge-opt').forEach(o => o.classList.remove('selected', 'correct', 'incorrect', 'dimmed'));
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
}
